  <title>Northline — Modern retail home</title>
  <style>
    :root {
      color-scheme: light;
      --bg: #f5f1eb;
      --surface: #ffffff;
      --surface-2: #f2ece4;
      --text: #171717;
      --muted: #5e5a54;
      --border: rgba(23, 23, 23, 0.12);
      --accent: #0f766e;
      --accent-2: #c2410c;
      --shadow: 0 18px 50px rgba(23, 23, 23, 0.08);
      --radius-xl: 32px;
      --radius-lg: 24px;
      --radius-md: 18px;
      --max: 1180px;
    }

    * {
      box-sizing: border-box;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      margin: 0;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top left, rgba(15, 118, 110, 0.12), transparent 34%),
        radial-gradient(circle at top right, rgba(194, 65, 12, 0.12), transparent 28%),
        linear-gradient(180deg, #faf7f2 0%, var(--bg) 100%);
      line-height: 1.5;
    }

    a {
      color: inherit;
      text-decoration: none;
    }

    img {
      max-width: 100%;
      display: block;
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      padding: 0.85rem 1rem;
      background: var(--text);
      color: #fff;
      border-radius: 999px;
      transform: translateY(-180%);
      transition: transform 0.2s ease;
      z-index: 1000;
    }

    .skip-link:focus {
      transform: translateY(0);
      outline: 3px solid #fff;
      outline-offset: 4px;
    }

    .page-shell {
      width: min(100%, calc(var(--max) + 2rem));
      margin: 0 auto;
      padding: 1rem;
    }

    header {
      padding: 0.5rem 0 1rem;
    }

    .topbar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      padding: 1rem 1.25rem;
      background: rgba(255, 255, 255, 0.72);
      backdrop-filter: blur(14px);
      border: 1px solid var(--border);
      border-radius: 999px;
      box-shadow: var(--shadow);
    }

    .brand {
      display: inline-flex;
      align-items: center;
      gap: 0.8rem;
      font-weight: 800;
      letter-spacing: 0.02em;
    }

    .brand-mark {
      width: 2.35rem;
      height: 2.35rem;
      border-radius: 999px;
      background: linear-gradient(135deg, var(--accent), #14b8a6);
      box-shadow: inset 0 0 0 1px rgba(255,255,255,0.45);
    }

    nav ul {
      display: flex;
      align-items: center;
      gap: 1rem;
      list-style: none;
      margin: 0;
      padding: 0;
      flex-wrap: wrap;
    }

    nav a {
      color: var(--muted);
      font-weight: 600;
      padding: 0.55rem 0.75rem;
      border-radius: 999px;
    }

    nav a:hover,
    nav a:focus-visible {
      color: var(--text);
      background: rgba(23, 23, 23, 0.06);
      outline: none;
    }

    .cta {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 0.55rem;
      padding: 0.9rem 1.2rem;
      border: 1px solid transparent;
      border-radius: 999px;
      font-weight: 700;
      background: var(--text);
      color: #fff;
      box-shadow: 0 8px 24px rgba(23, 23, 23, 0.18);
    }

    .cta:hover {
      background: #2a2a2a;
    }

    .cta:focus-visible,
    .filter-btn:focus-visible,
    .ghost-btn:focus-visible,
    .product-card button:focus-visible {
      outline: 3px solid #1d4ed8;
      outline-offset: 3px;
    }

    main {
      display: grid;
      gap: 1.25rem;
      padding-bottom: 2rem;
    }

    .hero,
    .section-card {
      background: rgba(255, 255, 255, 0.8);
      border: 1px solid var(--border);
      border-radius: var(--radius-xl);
      box-shadow: var(--shadow);
    }

    .hero {
      display: grid;
      grid-template-columns: 1.1fr 0.9fr;
      gap: 1rem;
      overflow: hidden;
    }

    .hero-copy {
      padding: clamp(1.25rem, 3vw, 2.75rem);
      display: grid;
      align-content: center;
      gap: 1rem;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      width: fit-content;
      padding: 0.45rem 0.8rem;
      border-radius: 999px;
      background: rgba(15, 118, 110, 0.1);
      color: var(--accent);
      font-size: 0.92rem;
      font-weight: 700;
    }

    h1 {
      margin: 0;
      font-size: clamp(2.5rem, 5vw, 4.8rem);
      line-height: 0.95;
      letter-spacing: -0.05em;
      max-width: 10ch;
    }

    .lede {
      margin: 0;
      max-width: 54ch;
      font-size: 1.05rem;
      color: var(--muted);
    }

    .hero-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.85rem;
      margin-top: 0.25rem;
    }

    .ghost-btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      padding: 0.9rem 1.2rem;
      border: 1px solid var(--border);
      border-radius: 999px;
      background: rgba(255,255,255,0.72);
      font-weight: 700;
    }

    .hero-visual {
      position: relative;
      min-height: 22rem;
      display: grid;
      place-items: stretch;
      padding: 1.2rem;
      background:
        radial-gradient(circle at 18% 18%, rgba(255, 255, 255, 0.8), transparent 18%),
        linear-gradient(135deg, rgba(15, 118, 110, 0.18), rgba(194, 65, 12, 0.18)),
        #ece5db;
    }

    .visual-panel {
      display: grid;
      gap: 1rem;
      border-radius: var(--radius-lg);
      background: rgba(255,255,255,0.68);
      padding: 1rem;
      backdrop-filter: blur(12px);
      align-content: end;
    }

    .visual-card {
      border-radius: 22px;
      background: linear-gradient(145deg, #111827, #1f2937);
      color: #fff;
      padding: 1.2rem;
      min-height: 11rem;
      display: grid;
      align-content: space-between;
      box-shadow: 0 18px 35px rgba(17, 24, 39, 0.3);
    }

    .visual-card span {
      display: inline-flex;
      width: fit-content;
      padding: 0.35rem 0.65rem;
      border-radius: 999px;
      background: rgba(255,255,255,0.14);
      font-size: 0.82rem;
      font-weight: 700;
    }

    .stats {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 0.75rem;
    }

    .stat {
      padding: 0.85rem;
      border-radius: 18px;
      background: rgba(255,255,255,0.78);
      border: 1px solid rgba(23, 23, 23, 0.08);
    }

    .stat strong {
      display: block;
      font-size: 1.2rem;
      margin-bottom: 0.15rem;
    }

    .section-card {
      padding: clamp(1.1rem, 2.5vw, 1.6rem);
    }

    .section-head {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 1rem;
      margin-bottom: 1rem;
    }

    .section-head h2 {
      margin: 0;
      font-size: clamp(1.45rem, 2vw, 2rem);
      letter-spacing: -0.03em;
    }

    .section-head p {
      margin: 0;
      color: var(--muted);
      max-width: 44ch;
    }

    .filters {
      display: flex;
      flex-wrap: wrap;
      gap: 0.6rem;
      margin: 1rem 0 1.1rem;
    }

    .filter-btn {
      appearance: none;
      border: 1px solid var(--border);
      background: rgba(255,255,255,0.92);
      color: var(--text);
      border-radius: 999px;
      padding: 0.7rem 1rem;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
    }

    .filter-btn[aria-pressed="true"] {
      background: var(--text);
      color: #fff;
      border-color: var(--text);
    }

    .section-meta {
      margin: 0 0 1rem;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .product-grid,
    .deal-grid,
    .editorial-grid {
      display: grid;
      gap: 1rem;
      grid-template-columns: repeat(12, minmax(0, 1fr));
    }

    .product-card {
      grid-column: span 3;
      display: grid;
      gap: 0.9rem;
      padding: 1rem;
      border-radius: 24px;
      border: 1px solid rgba(23, 23, 23, 0.08);
      background: linear-gradient(180deg, rgba(255,255,255,0.98), rgba(248,244,238,0.98));
    }

    .product-card[data-category="accessories"] {
      background: linear-gradient(180deg, rgba(250, 247, 242, 0.98), rgba(242, 236, 228, 0.98));
    }

    .product-art {
      border-radius: 22px;
      min-height: 12rem;
      background:
        radial-gradient(circle at 20% 20%, rgba(255,255,255,0.9), transparent 18%),
        linear-gradient(135deg, rgba(15, 118, 110, 0.75), rgba(194, 65, 12, 0.82));
      position: relative;
      overflow: hidden;
    }

    .product-art::before,
    .product-art::after {
      content: "";
      position: absolute;
      border-radius: 999px;
      background: rgba(255,255,255,0.2);
    }

    .product-art::before {
      width: 8.5rem;
      height: 8.5rem;
      inset: auto auto -2rem -1.2rem;
    }

    .product-art::after {
      width: 5rem;
      height: 5rem;
      inset: 1rem 1rem auto auto;
    }

    .product-card h3,
    .deal-card h3,
    .story-card h3 {
      margin: 0;
      font-size: 1.05rem;
    }

    .product-card p,
    .deal-card p,
    .story-card p {
      margin: 0;
      color: var(--muted);
    }

    .product-card footer,
    .deal-footer {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 0.75rem;
    }

    .price {
      font-weight: 800;
      font-size: 1.05rem;
    }

    .product-card button {
      border: 0;
      background: var(--text);
      color: #fff;
      padding: 0.78rem 1rem;
      border-radius: 999px;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
    }

    .badge {
      display: inline-flex;
      width: fit-content;
      padding: 0.35rem 0.6rem;
      border-radius: 999px;
      background: rgba(15, 118, 110, 0.12);
      color: var(--accent);
      font-size: 0.82rem;
      font-weight: 700;
    }

    .deal-card {
      grid-column: span 6;
      display: grid;
      gap: 1rem;
      padding: 1.2rem;
      border-radius: 26px;
      border: 1px solid rgba(23, 23, 23, 0.08);
      background:
        linear-gradient(140deg, rgba(17, 24, 39, 0.98), rgba(31, 41, 55, 0.98));
      color: #fff;
      min-height: 18rem;
    }

    .deal-card p,
    .deal-card .price {
      color: rgba(255,255,255,0.84);
    }

    .deal-card .badge {
      background: rgba(255,255,255,0.14);
      color: #fff;
    }

    .deal-card.alt {
      background:
        linear-gradient(140deg, rgba(194, 65, 12, 0.95), rgba(245, 158, 11, 0.92));
    }

    .deal-visual {
      border-radius: 22px;
      min-height: 8rem;
      background:
        radial-gradient(circle at 25% 25%, rgba(255,255,255,0.34), transparent 22%),
        radial-gradient(circle at 82% 25%, rgba(255,255,255,0.2), transparent 17%),
        linear-gradient(135deg, rgba(255,255,255,0.08), rgba(255,255,255,0.02));
    }

    .editorial-grid {
      align-items: stretch;
    }

    .story-card {
      grid-column: span 4;
      display: grid;
      gap: 0.9rem;
      padding: 1rem;
      border-radius: 24px;
      border: 1px solid rgba(23, 23, 23, 0.08);
      background: rgba(255,255,255,0.9);
    }

    .story-art {
      min-height: 11rem;
      border-radius: 20px;
      background: linear-gradient(135deg, #cbd5e1, #e2e8f0);
      position: relative;
      overflow: hidden;
    }

    .story-art::before {
      content: "";
      position: absolute;
      inset: auto 1rem 1rem auto;
      width: 6rem;
      height: 6rem;
      border-radius: 50%;
      background: rgba(15,118,110,0.42);
    }

    .story-art::after {
      content: "";
      position: absolute;
      inset: 1rem auto auto 1rem;
      width: 5rem;
      height: 5rem;
      border-radius: 1rem;
      background: rgba(194,65,12,0.45);
      transform: rotate(12deg);
    }

    footer.site-footer {
      padding: 1.4rem 0 2rem;
      color: var(--muted);
    }

    .footer-inner {
      display: flex;
      justify-content: space-between;
      gap: 1rem;
      flex-wrap: wrap;
      padding: 1rem 1.2rem;
      border-top: 1px solid var(--border);
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    [hidden] {
      display: none !important;
    }

    @media (max-width: 920px) {
      .hero {
        grid-template-columns: 1fr;
      }

      .product-card,
      .story-card {
        grid-column: span 6;
      }

      .deal-card {
        grid-column: span 12;
      }
    }

    @media (max-width: 700px) {
      .topbar,
      .section-head {
        align-items: start;
        flex-direction: column;
      }

      nav ul {
        gap: 0.4rem;
      }

      .stats {
        grid-template-columns: 1fr;
      }

      .product-card,
      .story-card {
        grid-column: span 12;
      }

      .hero-visual {
        min-height: 19rem;
      }
    }

    @media (forced-colors: active) {
      :root {
        --border: CanvasText;
      }

      * {
        forced-color-adjust: auto;
      }

      .hero,
      .section-card,
      .topbar,
      .product-card,
      .story-card,
      .deal-card {
        border: 1px solid CanvasText;
        box-shadow: none;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#maincontent">Skip to main content</a>

  <div class="page-shell">
    <header>
      <div class="topbar">
        <a class="brand" href="#maincontent">
          <span class="brand-mark" aria-hidden="true"></span>
          <span>Northline</span>
        </a>

        <nav aria-label="Primary">
          <ul>
            <li><a href="#featured">Featured</a></li>
            <li><a href="#deals">Deals</a></li>
            <li><a href="#stories">Stories</a></li>
          </ul>
        </nav>

        <a class="cta" href="#featured">Shop new arrivals</a>
      </div>
    </header>

    <main id="maincontent">
      <section class="hero" aria-labelledby="hero-title">
        <div class="hero-copy">
          <p class="eyebrow">Autumn essentials, refined</p>
          <h1 id="hero-title">Modern pieces for everyday retail living.</h1>
          <p class="lede">Discover a curated mix of featured products, time-limited deals, and editorial edits designed to make browsing feel calm, clear, and premium.</p>
          <div class="hero-actions">
            <a class="cta" href="#featured">Explore featured products</a>
            <a class="ghost-btn" href="#deals">See today&apos;s deals</a>
          </div>
        </div>

        <div class="hero-visual" aria-hidden="true">
          <div class="visual-panel">
            <div class="visual-card">
              <span>Editor&apos;s pick</span>
              <strong>Textured layers and warm neutrals built for the new season.</strong>
            </div>
            <div class="stats" aria-label="Store highlights">
              <div class="stat">
                <strong>24 hrs</strong>
                <span>express dispatch</span>
              </div>
              <div class="stat">
                <strong>4.8/5</strong>
                <span>customer rating</span>
              </div>
              <div class="stat">
                <strong>120+</strong>
                <span>fresh arrivals</span>
              </div>
            </div>
          </div>
        </div>
      </section>

      <section class="section-card" id="featured" aria-labelledby="featured-title">
        <div class="section-head">
          <div>
            <p class="badge">Featured products</p>
            <h2 id="featured-title">Curated picks</h2>
          </div>
          <p>Use the filters to narrow the selection. The count updates live for screen reader and sighted users alike.</p>
        </div>

        <div class="filters" role="group" aria-label="Featured product filters">
          <button class="filter-btn" type="button" aria-pressed="true" data-filter="all">All</button>
          <button class="filter-btn" type="button" aria-pressed="false" data-filter="apparel">Apparel</button>
          <button class="filter-btn" type="button" aria-pressed="false" data-filter="home">Home</button>
          <button class="filter-btn" type="button" aria-pressed="false" data-filter="accessories">Accessories</button>
        </div>

        <p class="section-meta" id="product-status" aria-live="polite">Showing 6 products.</p>

        <div class="product-grid" id="product-grid">
          <article class="product-card" data-category="apparel">
            <div class="product-art" aria-hidden="true"></div>
            <div>
              <p class="badge">New arrival</p>
              <h3>Merino travel overshirt</h3>
              <p>Structured enough for the office, soft enough for the weekend.</p>
            </div>
            <footer>
              <span class="price">$148</span>
              <button type="button">Quick add</button>
            </footer>
          </article>

          <article class="product-card" data-category="home">
            <div class="product-art" aria-hidden="true"></div>
            <div>
              <p class="badge">Best seller</p>
              <h3>Ambient linen throw</h3>
              <p>A layered neutral that adds warmth without visual clutter.</p>
            </div>
            <footer>
              <span class="price">$92</span>
              <button type="button">Quick add</button>
            </footer>
          </article>

          <article class="product-card" data-category="accessories">
            <div class="product-art" aria-hidden="true"></div>
            <div>
              <p class="badge">Limited</p>
              <h3>Leather sling bag</h3>
              <p>Compact, hands-free storage with a polished matte finish.</p>
            </div>
            <footer>
              <span class="price">$126</span>
              <button type="button">Quick add</button>
            </footer>
          </article>

          <article class="product-card" data-category="apparel">
            <div class="product-art" aria-hidden="true"></div>
            <div>
              <p class="badge">Editor&apos;s pick</p>
              <h3>Tailored relaxed trouser</h3>
              <p>Clean drape, comfortable movement, and a sharp cropped hem.</p>
            </div>
            <footer>
              <span class="price">$110</span>
              <button type="button">Quick add</button>
            </footer>
          </article>

          <article class="product-card" data-category="home">
            <div class="product-art" aria-hidden="true"></div>
            <div>
              <p class="badge">New arrival</p>
              <h3>Ceramic table lamp</h3>
              <p>Soft glow and sculptural presence for bedside or bookshelf styling.</p>
            </div>
            <footer>
              <span class="price">$164</span>
              <button type="button">Quick add</button>
            </footer>
          </article>

          <article class="product-card" data-category="accessories">
            <div class="product-art" aria-hidden="true"></div>
            <div>
              <p class="badge">Bundle ready</p>
              <h3>Canvas market tote</h3>
              <p>Oversized carryall for errands, commutes, and spontaneous getaways.</p>
            </div>
            <footer>
              <span class="price">$58</span>
              <button type="button">Quick add</button>
            </footer>
          </article>
        </div>
      </section>

      <section class="section-card" id="deals" aria-labelledby="deals-title">
        <div class="section-head">
          <div>
            <p class="badge">Deals</p>
            <h2 id="deals-title">Limited-time offers</h2>
          </div>
          <p>Two spotlight promos designed to feel editorial, not noisy.</p>
        </div>

        <div class="deal-grid">
          <article class="deal-card">
            <div class="deal-visual" aria-hidden="true"></div>
            <div>
              <p class="badge">Today only</p>
              <h3>Mix three essentials and save 20%</h3>
              <p>Stack layers, home accents, or accessories and unlock automatic savings at checkout.</p>
            </div>
            <div class="deal-footer">
              <span class="price">From $48</span>
              <a class="cta" href="#featured">Shop deal</a>
            </div>
          </article>

          <article class="deal-card alt">
            <div class="deal-visual" aria-hidden="true"></div>
            <div>
              <p class="badge">Members</p>
              <h3>Free express shipping on orders over $100</h3>
              <p>Fast, tracked delivery with no extra code needed for loyalty members.</p>
            </div>
            <div class="deal-footer">
              <span class="price">No code required</span>
              <a class="cta" href="#stories">Learn more</a>
            </div>
          </article>
        </div>
      </section>

      <section class="section-card" id="stories" aria-labelledby="stories-title">
        <div class="section-head">
          <div>
            <p class="badge">Editorial</p>
            <h2 id="stories-title">Style notes</h2>
          </div>
          <p>Short reads that help the shopping experience feel curated and useful.</p>
        </div>

        <div class="editorial-grid">
          <article class="story-card">
            <div class="story-art" aria-hidden="true"></div>
            <div>
              <h3>The capsule wardrobe formula</h3>
              <p>Five pieces, three textures, and a palette that moves from weekday to weekend without effort.</p>
            </div>
          </article>

          <article class="story-card">
            <div class="story-art" aria-hidden="true"></div>
            <div>
              <h3>How to style a warm neutral room</h3>
              <p>Bring depth with layered finishes, soft light, and one sculptural statement object.</p>
            </div>
          </article>

          <article class="story-card">
            <div class="story-art" aria-hidden="true"></div>
            <div>
              <h3>Our edit of functional accessories</h3>
              <p>Everyday carry essentials chosen for clean lines, resilience, and versatile color.</p>
            </div>
          </article>
        </div>
      </section>
    </main>

    <footer class="site-footer">
      <div class="footer-inner">
        <span>Northline retail home concept</span>
        <span>Clean design. Clear navigation. Built with plain HTML, CSS, and JavaScript.</span>
      </div>
    </footer>
  </div>

  <script>
    const filterButtons = Array.from(document.querySelectorAll('.filter-btn'));
    const productCards = Array.from(document.querySelectorAll('.product-card'));
    const status = document.getElementById('product-status');

    function updateProducts(filter) {
      let visibleCount = 0;

      productCards.forEach((card) => {
        const matches = filter === 'all' || card.dataset.category === filter;
        card.hidden = !matches;
        if (matches) {
          visibleCount += 1;
        }
      });

      status.textContent = `Showing ${visibleCount} product${visibleCount === 1 ? '' : 's'}.`;
    }

    filterButtons.forEach((button) => {
      button.addEventListener('click', () => {
        const filter = button.dataset.filter;

        filterButtons.forEach((item) => {
          item.setAttribute('aria-pressed', String(item === button));
        });

        updateProducts(filter);
      });
    });

    updateProducts('all');
